func TestLookupEveryMessage(t *testing.T) {
	for _, tt := range lookupCases() {
		t.Run(tt.name, func(t *testing.T) {
			got, ok := gem.Lookup(tt.want.Stream, tt.want.Function, tt.sender)
			if !ok {
				t.Fatalf("Lookup(%d, %d, %d): not found", tt.want.Stream, tt.want.Function, tt.sender)
			}

			if (got.Decode == nil) != (tt.decode == nil) {
				t.Fatalf("Decode: got nil %t, want nil %t", got.Decode == nil, tt.decode == nil)
			}

			if tt.decode != nil {
				decoded, err := got.Decode(tt.body)
				if err != nil {
					t.Fatalf("Decode: %v", err)
				}

				want, err := tt.decode(tt.body)
				if err != nil {
					t.Fatalf("the form's own decoder: %v", err)
				}

				assertDecoded(t, decoded, want)
			}

			got.Decode = nil
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("got %+v, want %+v", got, tt.want)
			}
		})
	}
}

func TestLookupUndefined(t *testing.T) {
	defined := map[[2]byte]bool{}
	for _, tt := range lookupCases() {
		defined[[2]byte{tt.want.Stream, tt.want.Function}] = true
	}

	for stream := range 256 {
		for function := range 256 {
			if defined[[2]byte{byte(stream), byte(function)}] {
				continue
			}

			for _, sender := range []gem.Role{gem.RoleHost, gem.RoleEquipment} {
				if _, ok := gem.Lookup(byte(stream), byte(function), sender); ok {
					t.Errorf("Lookup(%d, %d, %d): found a message the stream files do not define", stream, function, sender)
				}
			}
		}
	}
}
